+
+func SafeJoin(base, rel string) (string, error) {
+	abs := filepath.Join(base, rel)
+	if !HasPrefix(abs, base) {
+		return "", fmt.Errorf("%w: %q", ErrEscapesBase, rel)
+	}
+	return abs, nil
